    boatSeen: "船家想了想：「{n}？見過，是坐我的船過河的。那天雨很大，一路緊緊抓著船舷。」",
    boatUnseen: "船家搖頭：「{n}？沒見過。這幾天過河的人我都記得，沒有這個人。」",
    boatLocal: "船家笑了：「{n}是霜渡本地人，用不著坐船。」",
    boatNote: "渡口的船家沒見過這個人坐船來",
