    paperRate: 5,
    paperLabel: "拿紙錢換銅錢（紙錢 {p} 文 → 銅錢 {c} 文）", paperNone: "拿紙錢換銅錢（紙錢不夠 5 文）",
    paperDo: "老溫把那疊紙錢一張一張攤開，看了很久。\n「燒給城隍爺的紙錢，城隍廟收。五文紙錢，換一文銅錢。」\n他把紙錢投進香爐，從功德箱裡數了 {c} 文給你。",
    paperAsk: "老溫壓低聲音：「施主，這紙錢……是活人給的嗎？」",
