    lotMid: "中籤。「守得雲開見月明。」\n你把籤詩折好收進懷裡，心裡踏實了一點。（心神 +5）",
    lotBad: "下籤。「此身非我有，此屋非我家。」\n老溫把籤收了回去：「再求一次也一樣。回去吧。」（心神 −5）",
