    followed: "回去的路上，你一直聽見身後有腳步聲。你停，它也停。\n（有什麼東西跟著你回去了。今晚畫皮比較容易得手。）",
    registerLabel: "查戶籍（{c} 文）", registerPrice: 20, registerHan: 10,
