    registerDead: "鄒主簿翻了很久，手指停在一行字上：「{n}，{f}人氏……去年冬，歿。」\n他推了推鏡片：「死人，怎麼會來投宿？」",
    registerOk: "鄒主簿翻到{n}那一頁，對了對：「籍貫、年歲，都對得上。」\n他頓了一下：「不過啊，最近死的人太多，冊子沒除籍的也不少。對得上，不一定就是活人。」",
    registerNote: "戶籍上寫著，這個人已經死了",
