  townPeople: {
    zou: { name: "鄒主簿",
      intro: [["", "鄒主簿從冊子堆裡抬起頭，鏡片後面的眼睛瞇成一條縫。"], ["zou", "歸雁樓的掌櫃？查戶籍是吧。一個人二十文，官府的規矩。"]],
      chat: ["三十年了，霜渡每一個人的生老病死，都在我這幾本冊子裡。", "最近死的人太多，冊子都寫不下了。上頭還要我別記，說是會嚇到百姓。", "你那間歸雁樓啊……開了二十年了吧？奇怪，我怎麼找不到你的戶籍。"],
      chatAfter: ["（鄒主簿翻著冊子，頭也不抬）你的事，我不問了。冊子上沒有的人，我一向不問。", "上頭又來了公文，說城外的流民不准進城。……冊子寫不下，我就寫在背面。", "掌櫃的，要查誰，自己翻吧。我眼睛不好了。"] },
    xiaoqi: { name: "小七",
      intro: [["", "貨郎小七一看見你，就把撥浪鼓搖得咚咚響。"], ["xiaoqi", "掌櫃的！我這兒什麼都有：銅鏡、香灰、針頭線腦。您樓裡那些客人，我也什麼都打聽得到。"]],
      chat: ["銅鏡可是好東西。人照了是人，鬼照了……嘿，您自己試試。", "前陣子有個客人託我找一面『照不出人』的鏡子，出價很高。我找遍了北邊，都沒找到。", "那位託我找鏡子的客人啊……我想不起他長什麼樣子了。怪了，我記人的臉從來不會忘。"] },
    wen: { name: "老溫",
      intro: [["", "老溫睜開一隻眼睛，看了你很久，才把籤筒推過來。"], ["wen", "求籤五文，上香二十。施主……你身上，香火味很淡啊。"]],
      chat: ["城隍爺管的是這一城的生死。人死了，要到這裡來報到。", "這幾年，來報到的魂越來越少。不是死的人少了，是有些人死了，魂沒有來。", "施主，你求過很多次籤了吧？每一次，抽到的都是同一支。"] },
    meng: { name: "孟婆子",
      intro: [["", "孟婆子拄著鐵鍬，看見你的時候，整個人僵住了。"], ["meng", "……你、你是……（她揉了揉眼睛）不，不是。是我看錯了。老了，眼花了。"]],
      chat: ["這裡埋的人，我每一個都記得長什麼樣子。他們活著的時候沒人記得，死了總得有一個。", "二十年前那個冬天，亂葬崗埋不下了。有個伙夫每天推車送屍首過來，推到最後，連他自己……", "你長得很像一個人。一個我親手埋的人。"],
      chatAfter: ["（孟婆子替那座小墳拔了拔草）……你還會來看他，他會高興的。", "我老了，記性不好。可是那張臉，我到死都記得。", "雨停了以後，我想替這裡每一個人都立塊牌子。你要是有空，來幫我寫字吧。"] }
  },
