    wang:   "王嫂按著懷裡的家書，喃喃地說：「爹……你是不是，也遇過這種東西？」",
    tou:    "石頭一頭鑽到桌子底下，抱著膝蓋直發抖：「我、我就說{v}晚上會站在走廊上……」",
    gu:     "顧老瞇著眼，看了那張臉很久：「……這張臉，刻得太好了。不是人刻得出來的。」",
    chen:   "陳小六腿一軟，坐倒在地上：「就是這種……那天夜裡，就是這種東西……」",
    he:     "何老闆抓起鹽袋，抖著手在地上撒了一圈，把自己圍在中間：「別過來！都別過來！」",
    afu:    "阿福手裡的茶壺摔得粉碎：「掌、掌櫃的……我今天早上，還給{v}端過洗臉水……」",
    qin:    "秦嬸抄起灶上的菜刀，擋在大家前面：「呸！我就知道，這東西吃飯從來不動筷子！」",
