        [["", "那天夜裡，大廳的人都睡了。蘇姑娘抱著琵琶走到櫃台前。"], ["su", "這首曲子，我只彈給你一個人聽。"], ["", "琴聲很輕，像雨停之後的屋簷。彈到最後一個音，她沒有停，而是抬起頭看著你。"]],
        [["", "雨停的那個傍晚，蘇姑娘拉著你走到後院。天邊有一道很淡的晚霞。"], ["su", "我想好了。那首曲子，就叫《歸雁》。"], ["su", "雁子飛得再遠，也會回來。……我不走了。"]]
