      shen: [["", "你對沈霜說了心裡的話。"], ["shen", "（她沉默了很久，然後笑了，那道疤也跟著彎起來）……好。你要是敢反悔，我的劍可不認人。"]],
      yun:  [["", "你對雲道長說了心裡的話。"], ["yun", "（她把拂塵抱在胸前）……師父，弟子大概，回不去了。"]],
      ye:   [["", "你對葉姑娘說了心裡的話。"], ["ye", "（她握住你的手，貼在自己的臉上）你的心跳……這次，我一點也不會聽錯。"]],
      yagu: [["", "你對啞姑說了心裡的話。"], ["", "她看著你，眼淚一直掉。然後她拉起你的手，在你掌心，用力寫了一個字：「好」。"]]
