    returning: { title: "歸　雁", desc: "第十二夜，城門沒有開。\n天亮的時候，雨停了。{l}站在門口，等你一起去看渡口的第一班船。", bad: false },
    jealous: { title: "情　殺", desc: "你腳踏了太多條船。\n{k}說，不想跟別人分你。歸雁樓的帳本上，最後一筆是你自己的名字。", bad: true },
    shuraOne: { title: "修　羅　場", desc: "攻城那一夜，她們在大廳裡對質。\n最後留下來的，是{l}。其他人含著淚，在天亮前離開了。", bad: false },
    shuraNone: { title: "修　羅　場", desc: "攻城那一夜，她們在大廳裡對質。\n天亮的時候，她們都走了。你一個人守著歸雁樓，守著一屋子的回憶。", bad: true },
    shuraAll: { title: "修　羅　場", desc: "攻城那一夜，她們在大廳裡對質，吵了一整夜。\n天亮的時候，她們決定一起留下來。\n「便宜你了，」她們說，「可你要是敢再多一個……」", bad: false },
    // v0.8 主線：解開四層真相後，第十二夜門主來叩門
    peel: { title: "褪　皮", desc: "你當著門主的面，把那張穿了二十年的皮，一寸一寸撕了下來。\n天亮的時候，櫃台後面只剩一件空衣服。\n樓裡留下來的人說，掌櫃的出遠門了，總有一天會回來。", bad: false },
    result: { title: "成　果", desc: "門主很滿意。\n第二年春天，北邊十座城的渡口，都開了一間客棧。\n每一間的掌櫃，都長著你的臉。", bad: true },
    human: { title: "歸　人", desc: "「我是人。」你說。\n門主看了你很久。牠那張沒有五官的臉上，第一次出現了像是表情的東西。\n牠走進雨裡，再也沒有回來。天亮了，你和樓裡的人一起，到渡口去看第一班船。", bad: false },
    give: { title: "還　皮", desc: "你推著那輛桃木推車，帶著梁長生的腰牌，走回亂葬崗。\n你在老槐樹下，把這張皮還給了他。\n孟婆子替他重新立了木牌。木牌旁邊，多了一塊沒有名字的。", bad: false },
    faceless: { title: "無　面", desc: "第十二夜，城門沒有開。門主的面具，在你手裡。\n你推著那輛桃木推車，走回城外的亂葬崗，把三百一十二具屍首的名字，一個一個刻在木牌上。\n刻到最後一塊時，你寫下了自己的名字。歸雁樓的債，還清了。", bad: false }
