    shen: ["她拉過你的手，看著你掌心的舊繭：「這是什麼留下的？……不說也行。」她的拇指在上面輕輕擦了一下。", "你們並肩坐在屋簷下看雨。她的肩膀慢慢靠了過來，誰都沒有說話。", "她替你把衣領整理好，手停在你胸口：「……別亂動。我在聽你的心跳。」"],
    yun: ["她替你把脈，把了很久，眉頭越皺越緊：「……心跳太快了。是你的，還是貧道的？」", "你替她理好被風吹亂的道袍下襬。她低著頭，耳根紅了一片。", "她教你畫一道平安符。你的手抖了，她就握著你的手，一筆一筆畫完。"],
    ye: ["她把耳朵貼在你的手腕上數脈搏：「一、二、三……你騙人，你明明很緊張。」", "你牽著她在後院繞了一圈，替她說雨落在每一片葉子上的樣子。她聽得很認真。", "她把一根繡花針別在你的衣襟上：「這樣，我就摸得到你在哪裡了。」"],
    yagu: ["她在你的手背上畫了一隻小鳥，又在旁邊畫了另一隻，靠得很近。", "你替她挑掉頭髮上的木屑。她一動也不動，連呼吸都屏住了。", "她把炭筆塞進你手裡，要你也畫一張。你畫得很醜，她卻小心地把那張紙收進懷裡。"]
