    shen: [{ text: "沈霜扔給你一包肉乾：「走鏢時備的，比鹹菜管飽。」\n（糧食 +3）", food: 3 }, { text: "沈霜在你門外守了一整夜。天亮時，你頭一回睡得那麼沉。", sanity: 5 }],
