    shen: ["（她把劍擱在一邊）……今天不想練劍了。陪我坐一會兒。", "（她擦著劍）以前我只知道往前走。現在……我好像知道要往哪裡回來了。", "等這一切結束，教我認帳本。護院總得知道東家有多少錢吧。"],
